"""Empty Chair Concierge: customer-side zero-party intelligence demo.

A deliberately useful customer experience: build a portable tattoo profile, then
show exactly which volunteered signals improve M4's demand model. Demo-only data
is kept in memory and never triggers delivery.
"""
import json
import uuid
from fastapi import Form, Request
from fastapi.responses import HTMLResponse, JSONResponse
import app as core

_PROFILES = {}


def _profile_score(p):
    fields = ["styles", "placement", "budget", "timing", "short_notice", "artist_vibe", "travel", "project"]
    known = sum(bool(p.get(k)) for k in fields)
    return round(25 + 70 * known / len(fields))


@core.app.post("/api/concierge/profile")
def concierge_profile(request: Request, session_id: str = Form(""), project: str = Form(""), styles: str = Form(""), placement: str = Form(""), budget: str = Form(""), timing: str = Form(""), short_notice: str = Form(""), artist_vibe: str = Form(""), travel: str = Form("")):
    sid = session_id.strip() or f"conc_{uuid.uuid4().hex[:12]}"
    p = {"session_id": sid, "project": project.strip(), "styles": styles.strip(), "placement": placement.strip(), "budget": budget.strip(), "timing": timing.strip(), "short_notice": short_notice.strip(), "artist_vibe": artist_vibe.strip(), "travel": travel.strip()}
    before = 31
    after = _profile_score(p)
    _PROFILES[sid] = p
    signals = [{"label": k.replace("_", " ").title(), "value": v} for k,v in p.items() if k != "session_id" and v]
    return JSONResponse({"ok": True, "session_id": sid, "profile": p, "signals": signals, "m4_confidence_before": before, "m4_confidence_after": after, "value": {"readiness": "ready to match" if after >= 70 else "developing", "short_notice": p.get("short_notice") or "not specified", "budget": p.get("budget") or "not specified", "style": p.get("styles") or "open"}}, headers={"Cache-Control":"no-store"})


@core.app.get("/concierge", response_class=HTMLResponse)
def concierge_page(request: Request):
    return HTMLResponse(r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Empty Chair Concierge</title><style>
:root{--g:#a6ff2e;--bg:#070907;--p:#0d110d;--line:#273027;--ink:#edf4e9;--muted:#899386}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -10%,rgba(166,255,46,.08),transparent 35%),var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.wrap{max-width:1040px;margin:auto;padding:28px}.brand{font-weight:900;letter-spacing:.16em;border-bottom:1px solid var(--line);padding-bottom:18px}.hero{padding:64px 0 34px}.ey{font:700 10px ui-monospace,monospace;color:var(--g);letter-spacing:.14em;text-transform:uppercase}.hero h1{font-size:clamp(44px,7vw,78px);line-height:.94;letter-spacing:-.055em;margin:10px 0 16px;max-width:850px}.hero p{color:#a7afa3;line-height:1.65;max-width:690px}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.card{border:1px solid var(--line);background:var(--p);padding:22px}.q{margin-bottom:18px}.q label{display:block;font-size:11px;font-weight:800;margin-bottom:7px}.q input,.q textarea,.q select{width:100%;background:#080b08;border:1px solid #334033;color:var(--ink);padding:12px;font:inherit}.q textarea{min-height:76px}.btn{width:100%;padding:14px;background:var(--g);border:0;color:#081007;font-weight:900;letter-spacing:.08em;text-transform:uppercase;cursor:pointer}.cell{width:54px;height:54px;margin:10px 0 24px;border-radius:47% 53% 44% 56%;background:rgba(166,255,46,.15);box-shadow:0 0 30px rgba(166,255,46,.45);animation:b 3s ease-in-out infinite}@keyframes b{50%{transform:scale(1.14) rotate(7deg)}}.meter{height:8px;background:#161d16;margin:9px 0 5px}.meter i{display:block;height:100%;background:var(--g);width:31%;transition:1s}.signals{display:grid;gap:7px;margin-top:14px}.sig{border:1px solid #303b30;padding:10px}.sig b{font-size:10px;color:var(--g);text-transform:uppercase}.sig span{display:block;color:#b6bfb1;font-size:12px;margin-top:4px}.result{display:none}.gift{margin-top:18px;border-left:2px solid var(--g);padding:14px;background:#10160f}.gift strong{display:block;font-size:18px;margin-bottom:8px}.gift div{font-size:12px;color:#b6c0b2;line-height:1.7}@media(max-width:760px){.grid{grid-template-columns:1fr}.wrap{padding:18px}.hero{padding-top:42px}}</style></head><body><div class="wrap"><div class="brand">EMPTY CHAIR <span style="color:var(--g)">/ CONCIERGE</span></div><section class="hero"><div class="ey">Your tattoo profile belongs to you</div><h1>Know what you want. Be easier to match.</h1><p>Concierge turns the things tattoo shops usually have to guess into a useful profile for you: what you like, what you can spend, when you can move, and what kind of artist actually fits.</p></section><div class="grid"><div class="card"><form id="f"><div class="q"><label>What are you thinking about getting?</label><textarea name="project" placeholder="A black panther on my thigh, maybe palm-sized…"></textarea></div><div class="q"><label>Styles you actually like</label><input name="styles" placeholder="American traditional, blackwork, fine line…"></div><div class="q"><label>Placement</label><input name="placement" placeholder="Forearm, thigh, ribs…"></div><div class="q"><label>Comfortable budget</label><select name="budget"><option value="">Choose</option><option>$150–300</option><option>$300–600</option><option>$600–1,000</option><option>$1,000+</option></select></div><div class="q"><label>When do you want it?</label><select name="timing"><option value="">Choose</option><option>As soon as possible</option><option>Next 30 days</option><option>Next 3 months</option><option>Just exploring</option></select></div><div class="q"><label>If a great artist had a cancellation tomorrow?</label><select name="short_notice"><option value="">Choose</option><option>Text me — I can move fast</option><option>Maybe, with 2–3 days notice</option><option>I need to plan ahead</option></select></div><div class="q"><label>What matters in an artist?</label><input name="artist_vibe" placeholder="Traditional specialist, collaborative, quiet appointment…"></div><div class="q"><label>How far would you travel?</label><select name="travel"><option value="">Choose</option><option>15 miles</option><option>30 miles</option><option>60 miles</option><option>Worth traveling for the right artist</option></select></div><button class="btn">Build my tattoo profile</button></form></div><aside class="card"><div class="cell"></div><div class="ey">M4 signal visibility</div><h2 style="margin:8px 0">What changes when you tell us.</h2><p style="color:var(--muted);font-size:12px;line-height:1.6">No surveillance theater. These are signals you chose to give because they make matching more useful.</p><div style="font-size:11px">M4 confidence <b id="pct">31%</b></div><div class="meter"><i id="bar"></i></div><div id="result" class="result"><div id="signals" class="signals"></div><div class="gift"><strong>Your data gift</strong><div id="gift"></div></div></div></aside></div></div><script>const f=document.getElementById('f');f.onsubmit=async e=>{e.preventDefault();const r=await fetch('/api/concierge/profile',{method:'POST',body:new FormData(f),cache:'no-store'}),j=await r.json();if(!r.ok){alert(j.error||'Could not build profile');return}document.getElementById('pct').textContent=j.m4_confidence_after+'%';document.getElementById('bar').style.width=j.m4_confidence_after+'%';const s=document.getElementById('signals');s.innerHTML='';j.signals.forEach(x=>s.innerHTML+=`<div class="sig"><b>${x.label}</b><span>${x.value}</span></div>`);document.getElementById('gift').innerHTML=`Style: ${j.value.style}<br>Budget: ${j.value.budget}<br>Short-notice: ${j.value.short_notice}<br>Project readiness: ${j.value.readiness}<br><br><b style="color:var(--g)">M4 gained ${j.m4_confidence_after-j.m4_confidence_before} points of customer-model confidence from information you deliberately supplied.</b>`;document.getElementById('result').style.display='block';document.getElementById('result').scrollIntoView({behavior:'smooth'})};</script></body></html>''', headers={"Cache-Control":"no-store"})
